def L(kind, url, en=None, fr=None):
    """A link. kind selects the default label (see build.py LINK_LABELS)."""
    return (kind, url, en, fr)


def P(slug, name, en, fr, area="", kind=None, facts=None, links=(), badges=(),
      rating=None, price=None, maps=None, name_fr=None):
    return dict(slug=slug, name=name, name_fr=name_fr, en=en, fr=fr, area=area, kind=kind, facts=facts,
                links=list(links), badges=list(badges), rating=rating, price=price, maps=maps)


